.sc-tw :root{
            color-scheme: dark;
            --space: oklch(7% 0.02 280);
            --dust: oklch(70% 0.16 40);
            --iron: oklch(58% 0.05 35);
            --violet: oklch(57% 0.12 295);
            --ember: oklch(76% 0.16 55);
        }.sc-tw *{
            box-sizing: border-box;
        }.sc-tw html{
            scroll-behavior: smooth;
        }.sc-tw{
            margin: 0;
            overflow-x: hidden;
            color: white;
            font-family: 'Inter Tight', sans-serif;
            background: radial-gradient(circle at 20% 10%, rgba(255, 148, 70, .14), transparent 18%), radial-gradient(circle at 80% 15%, rgba(125, 88, 255, .11), transparent 18%), linear-gradient(180deg, oklch(8% 0.02 280) 0%, oklch(6% 0.02 280) 50%, oklch(5% 0.02 280) 100%);
        }.sc-tw body::before{
            content: '';
            position: fixed;
            inset: 0;
            pointer-events: none;
            background-image: linear-gradient(rgba(255, 255, 255, .028) 1px, transparent 1px), linear-gradient(90deg, rgba(255, 255, 255, .028) 1px, transparent 1px);
            background-size: 112px 112px;
            mask-image: radial-gradient(circle at center, black 30%, transparent 84%);
            opacity: .28;
            z-index: -2;
        }.sc-tw .copy{
            font-family: 'Inter Tight', sans-serif;
        }.sc-tw .serif{
            font-family: 'Cormorant Garamond', serif;
            letter-spacing: -0.06em;
        }.sc-tw .mono{
            font-family: 'Inter Tight', sans-serif;
        }.sc-tw .hud{
            background: rgba(255, 255, 255, .035);
            border: 1px solid rgba(255, 255, 255, .08);
            backdrop-filter: blur(40px) contrast(1.1);
            -webkit-backdrop-filter: blur(40px) contrast(1.1);
            box-shadow: inset 0 1px 0 rgba(255, 255, 255, .06), 0 18px 60px rgba(0, 0, 0, .46);
        }.sc-tw .aero{
            position: relative;
            overflow: hidden;
            border-radius: 999px;
            background: linear-gradient(180deg, rgba(255, 255, 255, .14), rgba(255, 255, 255, .04));
            border: 1px solid rgba(255, 255, 255, .12);
            box-shadow: inset 0 1px 0 rgba(255, 255, 255, .16), 0 0 0 1px rgba(255, 255, 255, .04), 0 20px 60px rgba(255, 148, 70, .08);
            transition: transform .55s cubic-bezier(.16, 1, .3, 1), box-shadow .55s ease;
        }.sc-tw .aero::before{
            content: '';
            position: absolute;
            inset: 0;
            border-radius: inherit;
            padding: 1px;
            background: linear-gradient(110deg, rgba(255, 255, 255, .12), rgba(255, 148, 70, .45), rgba(125, 88, 255, .25), rgba(255, 255, 255, .08));
            -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
            -webkit-mask-composite: xor;
            mask-composite: exclude;
            pointer-events: none;
        }.sc-tw .aero::after{
            content: '';
            position: absolute;
            inset: -120%;
            background: linear-gradient(120deg, transparent 44%, rgba(255, 255, 255, .32) 50%, transparent 56%);
            transform: translateX(-140%) rotate(12deg);
            animation: sheen 8s ease-in-out infinite;
            pointer-events: none;
            mix-blend-mode: screen;
        }.sc-tw .aero:hover{
            transform: translateY(-4px) scale(1.01);
            box-shadow: inset 0 1px 0 rgba(255, 255, 255, .16), 0 0 0 1px rgba(255, 148, 70, .16), 0 24px 70px rgba(0, 0, 0, .48);
        }.sc-tw .squircle{
            border-radius: 2.1rem;
        }.sc-tw .bloom{
            opacity: 0;
            transform: translateY(22px) scale(.98);
            animation: bloom .9s cubic-bezier(.16, 1, .3, 1) forwards;
            animation-timeline: view();
            animation-range: entry 10% cover 28%;
        }.sc-tw .pulse-text{
            display: inline-block;
            animation: pulsar 7s ease-in-out infinite;
            transform-origin: center bottom;
        }.sc-tw .hero-shell{
            position: relative;
            will-change: transform, filter;
            overflow: hidden;
            filter: drop-shadow(0 0 95px rgba(255, 148, 70, .16)) drop-shadow(0 0 80px rgba(125, 88, 255, .12));
        }.sc-tw .hero-shell::before{
            content: '';
            position: absolute;
            inset: -10%;
            background: radial-gradient(circle at 25% 30%, rgba(255, 148, 70, .18), transparent 22%), radial-gradient(circle at 70% 40%, rgba(125, 88, 255, .16), transparent 22%), radial-gradient(circle at 55% 60%, rgba(255, 255, 255, .05), transparent 28%);
            filter: blur(55px);
            pointer-events: none;
            z-index: 2;
        }.sc-tw .hero-video{
            transform-origin: center center;
            will-change: transform, filter;
        }.sc-tw .orbtag{
            background: rgba(255, 255, 255, .04);
            border: 1px solid rgba(255, 255, 255, .08);
            backdrop-filter: blur(26px) contrast(1.08);
            -webkit-backdrop-filter: blur(26px) contrast(1.08);
        }.sc-tw .ridges{
            position: relative;
            isolation: isolate;
        }.sc-tw .ridges::before{
            content: '';
            position: absolute;
            inset: auto 0;
            height: 1px;
            background: linear-gradient(90deg, transparent, rgba(255, 148, 70, .5), rgba(125, 88, 255, .55), transparent);
            filter: blur(.2px);
        }.sc-tw .hex{
            border-radius: 1.5rem;
            background: linear-gradient(180deg, rgba(255, 255, 255, .06), rgba(255, 255, 255, .02));
            border: 1px solid rgba(255, 255, 255, .08);
            box-shadow: inset 0 1px 0 rgba(255, 255, 255, .08), 0 12px 40px rgba(0, 0, 0, .3);
        }.sc-tw .fracture{
            border-radius: 1.5rem;
            background: linear-gradient(180deg, rgba(255, 255, 255, .06), rgba(255, 255, 255, .02));
            border: 1px solid rgba(255, 255, 255, .08);
            box-shadow: inset 0 1px 0 rgba(255, 255, 255, .08), 0 12px 40px rgba(0, 0, 0, .3);
        }.sc-tw .fade-line{
            height: 1px;
            background: linear-gradient(90deg, transparent, rgba(255, 148, 70, .32), rgba(125, 88, 255, .32), transparent);
        }.sc-tw .scroll-strip{
            display: grid;
            grid-auto-flow: column;
            grid-auto-columns: 84%;
            gap: 1rem;
            overflow-x: auto;
            scroll-snap-type: x mandatory;
            scrollbar-width: none;
        }.sc-tw .scroll-strip::-webkit-scrollbar{
            display: none;
        }.sc-tw .strip-card{
            scroll-snap-align: start;
            min-height: 320px;
        }.sc-tw .core-ring{
            width: min(72vw, 42rem);
            aspect-ratio: 1;
            border-radius: 999px;
            position: relative;
            background: radial-gradient(circle, rgba(255, 255, 255, .08), rgba(255, 255, 255, .03) 52%, transparent 70%);
            border: 1px solid rgba(255, 255, 255, .08);
            box-shadow: 0 0 120px rgba(125, 88, 255, .12), inset 0 0 80px rgba(255, 255, 255, .03);
        }.sc-tw .core-ring::before{
            content: '';
            position: absolute;
            inset: 12%;
            border-radius: 999px;
            border: 1px solid rgba(255, 255, 255, .1);
            box-shadow: inset 0 0 60px rgba(255, 148, 70, .08);
        }.sc-tw .float-label{
            position: absolute;
            padding: 12px 16px;
            border-radius: 999px;
            font-size: 11px;
            letter-spacing: .2em;
            text-transform: uppercase;
            background: rgba(255, 255, 255, .035);
            border: 1px solid rgba(255, 255, 255, .08);
            backdrop-filter: blur(40px) contrast(1.1);
            -webkit-backdrop-filter: blur(40px) contrast(1.1);
        }.sc-tw .mega-title{
            text-shadow: 0 0 30px rgba(255, 255, 255, .08);
        }

        @keyframes bloom {to{
                opacity: 1;
                transform: translateY(0) scale(1);
            }
        }

        @keyframes sheen {to{
                transform: translateX(240%) rotate(12deg);
            }
        }

        @keyframes pulsar {0%,100%{
                transform: scale(1);
            }50%{
                transform: scale(1.02);
            }
        }

        @keyframes heroScale {from{
                transform: scale(1.02);
            }to{
                transform: scale(1.14);
            }
        }.sc-tw .hero-scale{
            animation: heroScale linear both;
            animation-timeline: scroll(root);
            transform-origin: center center;
        }.sc-tw ::view-transition-old(root),.sc-tw ::view-transition-new(root){
            animation-duration: .72s;
            animation-timing-function: cubic-bezier(.16, 1, .3, 1);
